g=[[1]*16 for _ in range(25)]
orig={(1,3):9,(2,4):9,(2,5):9,(3,4):7,(4,3):7,(3,5):6,(4,6):6}
for (r,c),v in orig.items():g[r][c]=v
# extend diagonal runs outward, stopping at non-background objects
for r,c,v,dr,dc in [(1,3,9,-1,-1),(2,4,9,1,1),(4,3,7,1,-1),(3,4,7,-1,1),(3,5,6,-1,-1),(4,6,6,1,1)]:
    rr,cc=r+dr,c+dc
    while 0<=rr<25 and 0<=cc<16 and g[rr][cc]==1:
        g[rr][cc]=v; rr+=dr;cc+=dc
print('\n'.join(' '.join(map(str,row)) for row in g))
